// Campus 3D: the prop kit (visual rehaul 2026-11-13). kit.json holds 94 low-poly props as plain numbers: 82 built in
// Blender from code (tools/campus-assets/build_*.py: trees, benches, planters, rooftop gear, furniture, most store
// items) and 12 generated by the owner with a 3D generation service (paid plan, owner confirmed) and converted in Blender (the
// landmarks fountain, bandstand, food truck, balloon, bus and car, and six store items). THIRD-PARTY-NOTICES.md lists them.
// Each prop has named parts of flat-shaded triangles with one colour per triangle:
//   body: its own colours · tint*: greys, coloured per instance (tree crowns) · glow: unlit (lamp heads, beacons).
// loadKit() fetches it once; if it fails the campus falls back to its old code-drawn shapes (kit stays null).
import * as THREE from "three";

let kit = null;
const cache = new Map();
export async function loadKit() {
  if (kit) return kit;
  try { const r = await fetch(`/campus/3d/kit.json${window.campusAssetV?.kit ? `?v=${window.campusAssetV.kit}` : ""}`); if (r.ok) kit = await r.json(); } catch { kit = null; }
  return kit;
}
export const hasKit = (name) => !!kit?.props?.[name];

function unpack(part) {
  if (part.p) return { p: Float32Array.from(part.p), c: Uint8Array.from(part.c) };
  const S = kit.packed?.scale || 4096;
  const b = Uint8Array.from(atob(part.p64), (ch) => ch.charCodeAt(0)), i16 = new Int16Array(b.buffer);
  const p = new Float32Array(i16.length); for (let i = 0; i < i16.length; i++) p[i] = i16[i] / S;
  return { p, c: Uint8Array.from(atob(part.c64), (ch) => ch.charCodeAt(0)) };
}
// A part's geometry (non-indexed triangles with face normals and a colour attribute). Shared: clone before changing it.
export function kitGeo(name, part = "body") {
  const key = name + "/" + part;
  if (cache.has(key)) return cache.get(key);
  const src = kit?.props?.[name]?.[part];
  if (!src) return null;
  const { p, c } = unpack(src), n = p.length / 3, col = new Float32Array(n * 3);
  const lin = (v) => { v /= 255; return v <= 0.04045 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4); }; // sRGB bytes -> linear, like three's Color
  for (let t = 0; t < n / 3; t++) for (let k = 0; k < 3; k++) { const r = lin(c[t * 3]), g = lin(c[t * 3 + 1]), b2 = lin(c[t * 3 + 2]); col.set([r, g, b2], (t * 3 + k) * 3); }
  const g = new THREE.BufferGeometry();
  g.setAttribute("position", new THREE.BufferAttribute(p, 3)); g.setAttribute("color", new THREE.BufferAttribute(col, 3));
  g.computeVertexNormals(); g.computeBoundingBox(); g.computeBoundingSphere();
  cache.set(key, g);
  return g;
}
export const kitParts = (name) => Object.keys(kit?.props?.[name] || {});
// Every non-tint, non-glow part of a prop merged into one geometry, placed by matrix (for merging into a painted mesh).
export function kitSolid(name, matrix) {
  const geos = kitParts(name).filter((k) => !k.startsWith("tint") && k !== "glow").map((k) => kitGeo(k === "body" ? name : name, k)).filter(Boolean);
  if (!geos.length) return null;
  const n = geos.reduce((a, g) => a + g.attributes.position.count, 0), pos = new Float32Array(n * 3), col = new Float32Array(n * 3);
  let o = 0;
  for (const g of geos) { pos.set(g.attributes.position.array, o * 3); col.set(g.attributes.color.array, o * 3); o += g.attributes.position.count; }
  const out = new THREE.BufferGeometry().setAttribute("position", new THREE.BufferAttribute(pos, 3)).setAttribute("color", new THREE.BufferAttribute(col, 3));
  if (matrix) out.applyMatrix4(matrix);
  out.computeVertexNormals();
  return out;
}
// The size of a prop's bounding box (all parts).
export function kitSize(name) {
  const box = new THREE.Box3();
  for (const k of kitParts(name)) { const g = kitGeo(name, k); if (g) box.union(g.boundingBox); }
  return box;
}
